package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme. On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from a Reader and returns a Theme. On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		return DarkTheme(), err
	}

	theme := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse generic colors
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, val := range colors {
			if hexStr, ok := val.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse dark variant colors
	if colorsDark, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, val := range colorsDark {
			if hexStr, ok := val.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colorsDark[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse light variant colors
	if colorsLight, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, val := range colorsLight {
			if hexStr, ok := val.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colorsLight[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse sizes
	if sizes, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, val := range sizes {
			if floatVal, ok := val.(float64); ok {
				theme.sizes[fyne.ThemeSizeName(name)] = float32(floatVal)
			}
		}
	}

	// Parse fonts
	if fonts, ok := raw["Fonts"].(map[string]interface{}); ok {
		for style, val := range fonts {
			if uriStr, ok := val.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					theme.fonts[style] = &fyne.StaticResource{
						StaticName:    uri.Name(),
						StaticContent: []byte{}, // Content would be loaded separately
					}
				}
			}
		}
	}

	// Parse icons
	if icons, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, val := range icons {
			if uriStr, ok := val.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					theme.icons[fyne.ThemeIconName(name)] = &fyne.StaticResource{
						StaticName:    uri.Name(),
						StaticContent: []byte{}, // Content would be loaded separately
					}
				}
			}
		}
	}

	return theme, nil
}

// parseHexColor parses a hex color string and returns a color.Color.
// Supports formats: #rgb, #rgba, #rrggbb, #rrggbbaa (with or without # prefix)
// 3-digit: abc -> aabbcc
// 4-digit: abcd -> aabbccdd
// 6-digit: a1b2c3 -> a1b2c3ff
// 8-digit: a1b2c3f4 -> a1b2c3f4
func parseHexColor(s string) (color.Color, error) {
	s = strings.TrimPrefix(s, "#")

	var r, g, b, a uint8

	switch len(s) {
	case 3:
		// rgb -> rrggbb
		vals, err := parseHexDigits(s, 1)
		if err != nil {
			return color.Transparent, err
		}
		r, g, b, a = vals[0]*17, vals[1]*17, vals[2]*17, 255
	case 4:
		// rgba -> rrggbbaa
		vals, err := parseHexDigits(s, 1)
		if err != nil {
			return color.Transparent, err
		}
		r, g, b, a = vals[0]*17, vals[1]*17, vals[2]*17, vals[3]*17
	case 6:
		// rrggbb
		vals, err := parseHexDigits(s, 2)
		if err != nil {
			return color.Transparent, err
		}
		r, g, b, a = vals[0], vals[1], vals[2], 255
	case 8:
		// rrggbbaa
		vals, err := parseHexDigits(s, 2)
		if err != nil {
			return color.Transparent, err
		}
		r, g, b, a = vals[0], vals[1], vals[2], vals[3]
	default:
		return color.Transparent, fmt.Errorf("invalid hex color format: %s", s)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigits parses hex string into byte values, reading 'step' characters at a time
func parseHexDigits(s string, step int) ([]uint8, error) {
	result := make([]uint8, 0, len(s)/step)
	for i := 0; i < len(s); i += step {
		val, err := strconv.ParseUint(s[i:i+step], 16, 8)
		if err != nil {
			return nil, err
		}
		result = append(result, uint8(val))
	}
	return result, nil
}

type jsonTheme struct {
	colors      map[fyne.ThemeColorName]color.Color
	colorsDark  map[fyne.ThemeColorName]color.Color
	colorsLight map[fyne.ThemeColorName]color.Color
	sizes       map[fyne.ThemeSizeName]float32
	fonts       map[string]fyne.Resource
	icons       map[fyne.ThemeIconName]fyne.Resource
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == fyne.VariantDark {
		if c, ok := t.colorsDark[name]; ok {
			return c
		}
	} else if variant == fyne.VariantLight {
		if c, ok := t.colorsLight[name]; ok {
			return c
		}
	}

	// Check generic colors
	if c, ok := t.colors[name]; ok {
		return c
	}

	// Fall back to default theme
	return DarkTheme().Color(name, variant)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if icon, ok := t.icons[name]; ok {
		return icon
	}
	return DarkTheme().Icon(name)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	var key string
	if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else if style.Italic {
		key = "italic"
	} else if style.Monospace {
		key = "monospace"
	} else {
		key = "regular"
	}

	if font, ok := t.fonts[key]; ok {
		return font
	}
	return DarkTheme().Font(style)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[name]; ok {
		return size
	}
	return DarkTheme().Size(name)
}

