package binding

import (
	"fmt"
	"sync"

	"fyne.io/fyne/v2/storage"
)

// StringFormat supports binding a formatted string from a variable number of input DataItem bindings.
//
// Since: 2.5
type StringFormat interface {
	String
	AddListener(DataListener)
	RemoveListener(DataListener)
}

// NewSprintf returns a new StringFormat binding that formats its output using the specified format string and data bindings.
// The format string follows the same rules as fmt.Sprintf. The binding listens to all input sources and updates when any changes.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) StringFormat {
	s := &boundSprintf{
		format:   format,
		bindings: bindings,
	}

	// Listen to all input bindings
	listener := NewDataListener(func() {
		s.lock.Lock()
		defer s.lock.Unlock()
		s.trigger()
	})

	for _, b := range bindings {
		b.AddListener(listener)
	}

	return s
}

// StringToStringWithFormat creates a bidirectional binding that formats a string binding.
// If format is "%s", the original binding is returned directly for efficiency.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str).(String)
}

type boundSprintf struct {
	base

	format   string
	bindings []DataItem
	lock     sync.RWMutex
}

func (s *boundSprintf) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	// Gather all values from bound items
	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		switch typed := b.(type) {
		case String:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Int:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Float:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Bool:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Bytes:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Rune:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case URI:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Untyped:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		default:
			values[i] = nil
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *boundSprintf) Set(str string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Parse the string back into component values
	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		switch b.(type) {
		case String:
			var val string
			values[i] = &val
		case Int:
			var val int
			values[i] = &val
		case Float:
			var val float64
			values[i] = &val
		case Bool:
			var val bool
			values[i] = &val
		case Bytes:
			// Bytes cannot be round-tripped through string formatting
			return fmt.Errorf("cannot set Bytes binding through formatted string")
		case Rune:
			var val rune
			values[i] = &val
		case URI:
			var val string
			values[i] = &val
		case Untyped:
			var val interface{}
			values[i] = &val
		default:
			return fmt.Errorf("unsupported binding type")
		}
	}

	// Parse using Sscanf
	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.bindings) {
		return fmt.Errorf("expected %d values, got %d", len(s.bindings), n)
	}

	// Set each binding
	for i, b := range s.bindings {
		switch typed := b.(type) {
		case String:
			if err := typed.Set(*values[i].(*string)); err != nil {
				return err
			}
		case Int:
			if err := typed.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Float:
			if err := typed.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Bool:
			if err := typed.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case Rune:
			if err := typed.Set(*values[i].(*rune)); err != nil {
				return err
			}
		case URI:
			uri, err := storage.ParseURI(*values[i].(*string))
			if err != nil {
				return err
			}
			if err := typed.Set(uri); err != nil {
				return err
			}
		case Untyped:
			if err := typed.Set(*values[i].(*interface{})); err != nil {
				return err
			}
		}
	}

	return nil
}

